        "title": "Allow only read statements",
        "given": "a submitted query",
        "when": "the parsed statement is anything other than a single read-only SELECT (no DML, DDL, or multiple statements)",
        "then": "it is refused and the connection remains in a read-only transaction"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "One expensive query starves the replica and the systems depending on it",
      "scenario": "A user writes an unbounded cross join or a full scan over large tables, or opens many tabs doing so. The replica's CPU, memory and replication lag blow up, so every report and any service reading from that replica slows down or times out. No query timeout, row cap or concurrency limit is described, so a single untrained user can cause an outage by accident or on purpose.",
      "component": "Production read replica",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        {
          "quote": "Business users get a reporting dashboard with a free SQL editor connected to the production replica"
        }
      ],
