        "when": "the query exceeds the configured statement timeout, row limit, result size or per-user concurrent query limit",
        "then": "it is cancelled server-side and the user gets a clear error, with the replica left healthy"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Dashboard with direct database reach has no stated authentication or authorisation model",
      "scenario": "The design names 'business users' as the audience but no sign-in, group membership or approval step. An internal attacker, contractor or anyone who reaches the internal URL (including via SSRF or a stolen laptop session) opens the editor and queries production data directly. The deterministic scan also reports no auth for this work item.",
      "component": "Reporting dashboard UI",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "Business users get a reporting dashboard with a free SQL editor connected to the production replica"
        },
        {
          "quote": "\"exposure\":\"internal\",\"llmFeatures\":false,\"fileUpload\":false,\"auth\":false"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-306", "CWE-862"],
      "plainLanguage": "Nothing in the design says who is allowed in, so anyone who finds the page could query live data.",
      "requirement": {
        "title": "Gate the SQL editor behind authentication and an explicit entitlement",
        "given": "a request to the dashboard or its query endpoint",
        "when": "the caller is unauthenticated or is not a member of the approved reporting group",
        "then": "the request is denied and no database connection is opened"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Results can be exported in bulk with no masking or volume control",
      "scenario": "Because users 'build their own reports', query output is downloadable or shareable. An insider runs one query that returns millions of customer rows including identifiers and contact details, then exports it to a spreadsheet outside the controlled system. Without masking of sensitive columns and limits on export volume, large-scale data theft looks like normal reporting activity.",
      "component": "Reporting dashboard export",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "so they can build their own reports"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-359", "CWE-213"],
      "plainLanguage": "Someone could download a copy of the whole customer list as if it were just another report.",
      "requirement": {
        "title": "Mask sensitive columns and cap exports",
        "given": "a query result containing columns classified as personal or sensitive",
        "when": "the user views or exports the result",
        "then": "those columns are masked unless the user holds a specific entitlement, and exports above the configured row threshold require approval"
      }
    },
    {
      "stride": "Repudiation",
      "title": "No way to prove which person extracted which data",
      "scenario": "Queries reach the replica through a shared service connection, so database logs show the service, not the person. After a leak of customer data the team cannot tell which of the business users ran the extracting query, and a malicious insider can deny it. With arbitrary SQL as the access path, per-query attribution is the only control that makes misuse detectable.",
      "component": "Query execution service",
      "likelihood": 4,
      "impact": 3,
      "evidence": [
        {
          "quote": "a free SQL editor connected to the production replica so they can build their own reports"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-778"],
      "plainLanguage": "If data leaks, nobody can prove whose query pulled it.",
      "requirement": {
        "title": "Attribute every query to a named user",
        "given": "a query submitted through the editor",
        "when": "it is executed against the replica",
        "then": "the full SQL text, user identity, timestamp and row count are stored in a tamper-resistant log and the database session carries the end-user identity"
      }
    }
  ]
}
